`timescale 1ns/1ps
module tb_spi_master; reg clk=0,rst_n=0,start=0; reg [7:0] data_in=8'hA5; wire sclk,mosi,busy,done; spi_master dut(clk,rst_n,start,data_in,sclk,mosi,busy,done); always #5 clk=~clk;
 initial begin rst_n=1; #2; rst_n=0; #1; if(!done&&sclk===0)$display("IVERILOG_AI_RESULT {\"ok\":true,\"test_id\":\"reset\"}"); else $display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"reset\"}"); rst_n=1; @(negedge clk); start=1; @(negedge clk); start=0; if(!busy)$display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"start_busy\",\"signal\":\"busy\",\"expected\":1,\"actual\":%0d}",busy); else $display("IVERILOG_AI_RESULT {\"ok\":true,\"test_id\":\"start_busy\"}"); repeat(30) @(negedge clk); if(!busy)$display("IVERILOG_AI_RESULT {\"ok\":true,\"test_id\":\"done\"}"); else $display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"done\"}"); $finish; end endmodule
